<?php namespace App\Filament\Resources\MediaAssetResource\Pages; use App\Filament\Resources\MediaAssetResource; use App\Services\MediaIngestor; use Filament\Actions\Action; use Filament\Forms\Components\{FileUpload,TextInput,Textarea}; use Filament\Resources\Pages\ListRecords; class ListMediaAssets extends ListRecords {protected static string $resource=MediaAssetResource::class; protected function getHeaderActions():array{return [Action::make('upload')->label('Importer des images')->icon('heroicon-o-arrow-up-tray')->form([FileUpload::make('file')->label('Image')->required()->acceptedFileTypes(['image/jpeg','image/png','image/webp'])->maxSize(10240)->storeFiles(false),TextInput::make('alt_text')->label('Texte alternatif')->maxLength(255),Textarea::make('caption')->label('Légende')->maxLength(1000)])->action(fn(array $data)=>app(MediaIngestor::class)->ingest($data['file'],$data['alt_text']??null,$data['caption']??null))];}}
